class Solution {
public:
    long long pickGifts(vector<int>& gifts, int k) {
        priority_queue<int> pq(gifts.begin(), gifts.end());
        while (k-- > 0) {
            int top = pq.top();
            pq.pop();
            pq.push((int)sqrt(top));
        }
        long long left = 0;
        while (!pq.empty()) {
            left += pq.top();
            pq.pop();
        }
        return left;
    }
};
